-- seed 914 :: fr translations 281-300

INSERT INTO translation_intake (original, locale, body) VALUES
    ('A hero is an ordinary individual who finds the strength to persevere and endure in spite of overwhelming obstacles.', 'fr',
     'Un héros est une personne ordinaire qui trouve la force de persévérer et d''endurer malgré des obstacles écrasants.'),
    ('What lies behind us and what lies before us are tiny matters compared to what lies within us.', 'fr',
     'Ce qui est derrière nous et ce qui est devant nous sont peu de chose comparé à ce qui est en nous.'),
    ('The greatest test of courage on earth is to bear defeat without losing heart.', 'fr',
     'La plus grande épreuve de courage sur terre est de supporter la défaite sans perdre cœur.'),
    ('Of all the virtues we can learn, no trait is more useful, more essential for survival, and more likely to improve the quality of life than the ability to transform adversity into an enjoyable challenge.', 'fr',
     'De toutes les vertus que nous pouvons acquérir, aucune n''est plus utile, plus essentielle à la survie et plus à même d''améliorer la qualité de vie que la capacité de transformer l''adversité en un défi agréable.');
